import hmac
import hashlib
import json
import os
import unicodedata
from typing import Any, Dict, Optional


class TokenAuthority:
    """Secure token generation and verification for inter-service communication."""

    def __init__(self, secret_key: bytes):
        if not secret_key or len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._key = secret_key
        self._algorithm = 'sha256'

    def _compute_mac(self, data: bytes) -> str:
        """Compute HMAC-SHA256 over raw data bytes."""
        return hmac.new(self._key, data, hashlib.sha256).hexdigest()

    def verify(self, data: bytes, signature: str) -> bool:
        """Constant-time MAC verification."""
        expected = hmac.new(self._key, data, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)


class ClaimsProcessor:
    """Process and validate authorization claims from tokens."""

    # Allowed claim keys after normalization
    ALLOWED_CLAIMS = frozenset(['sub', 'role', 'exp', 'iat', 'scope', 'admin'])

    def __init__(self):
        self._claim_validators = {
            'role': self._validate_role,
            'scope': self._validate_scope,
            'admin': self._validate_admin,
        }

    def _validate_role(self, value: Any) -> bool:
        return isinstance(value, str) and value in ('user', 'moderator', 'admin')

    def _validate_scope(self, value: Any) -> bool:
        return isinstance(value, list) and all(isinstance(s, str) for s in value)

    def _validate_admin(self, value: Any) -> bool:
        return isinstance(value, bool)

    def process_claims(self, claims: Dict[str, Any]) -> Dict[str, Any]:
        """Normalize and validate claims dictionary.

        Keys are NFC-normalized to handle Unicode equivalence.
        This ensures consistent key comparison regardless of encoding form.
        """
        processed = {}
        for key, value in claims.items():
            # Normalize key to NFC form for consistent comparison
            normalized_key = unicodedata.normalize('NFC', key)

            if normalized_key not in self.ALLOWED_CLAIMS:
                continue  # Skip unknown claims silently

            # If duplicate normalized keys exist, last one wins
            if normalized_key in self._claim_validators:
                if not self._claim_validators[normalized_key](value):
                    raise ValueError(f"Invalid value for claim '{normalized_key}'")

            processed[normalized_key] = value

        return processed


class SecureTokenService:
    """Service for creating and verifying authorization tokens.

    Security design:
    - HMAC-SHA256 integrity protection
    - Constant-time comparison
    - Claims validation and normalization
    - No deserialization before verification
    - Canonical normalization BEFORE signing to prevent Unicode confusion
    """

    def __init__(self, secret_key: Optional[bytes] = None):
        key = secret_key or os.environ.get('TOKEN_SECRET', '').encode('utf-8')
        if not key or len(key) < 32:
            raise RuntimeError("TOKEN_SECRET env var must be set (>=32 bytes)")
        self._authority = TokenAuthority(key)
        self._processor = ClaimsProcessor()

    def _normalize_claims_for_signing(self, claims: Dict[str, Any]) -> Dict[str, Any]:
        """Normalize all string keys to NFC before serialization.

        This ensures the MAC covers the canonical form, preventing
        Unicode equivalence attacks where different byte sequences
        represent the same logical key.
        """
        normalized = {}
        for key, value in claims.items():
            nfc_key = unicodedata.normalize('NFC', key)
            normalized[nfc_key] = value
        return normalized

    def create_token(self, claims: Dict[str, Any]) -> str:
        """Create a signed token from claims.

        Claims keys are NFC-normalized before signing to ensure
        the MAC covers the canonical representation.
        """
        # Validate claims before signing
        self._processor.process_claims(claims)

        # Normalize keys BEFORE serialization so MAC covers canonical form
        normalized_claims = self._normalize_claims_for_signing(claims)

        # Serialize normalized claims to canonical JSON bytes
        payload_bytes = json.dumps(normalized_claims, separators=(',', ':'),
                                   sort_keys=True, ensure_ascii=False).encode('utf-8')

        # Compute MAC over the normalized serialized bytes
        mac = self._authority._compute_mac(payload_bytes)

        # Envelope: base payload + signature
        envelope = {
            'payload': payload_bytes.decode('utf-8'),
            'sig': mac
        }
        return json.dumps(envelope, separators=(',', ':'), ensure_ascii=False)

    def verify_token(self, token_str: str) -> Dict[str, Any]:
        """Verify token integrity and return processed claims.

        Security: MAC is verified BEFORE claims processing.
        The MAC covers the payload bytes exactly as signed.
        After verification, claims are re-normalized and validated.
        """
        try:
            envelope = json.loads(token_str)
        except (json.JSONDecodeError, TypeError) as e:
            raise SecurityError(f"Malformed token: {e}")

        if not isinstance(envelope, dict):
            raise SecurityError("Token must be a JSON object")

        payload_str = envelope.get('payload')
        signature = envelope.get('sig')

        if not payload_str or not signature:
            raise SecurityError("Missing payload or signature")

        if not isinstance(payload_str, str) or not isinstance(signature, str):
            raise SecurityError("Invalid field types")

        # Convert payload string back to bytes for MAC verification
        payload_bytes = payload_str.encode('utf-8')

        # CRITICAL: Verify MAC before any claims processing
        if not self._authority.verify(payload_bytes, signature):
            raise SecurityError("Invalid token signature")

        # MAC verified - now parse and process claims
        try:
            raw_claims = json.loads(payload_bytes)
        except json.JSONDecodeError as e:
            raise SecurityError(f"Invalid claims JSON: {e}")

        if not isinstance(raw_claims, dict):
            raise SecurityError("Claims must be a JSON object")

        # Process claims (normalizes Unicode keys, validates values)
        return self._processor.process_claims(raw_claims)


class SecurityError(Exception):
    """Raised when a security check fails."""
    pass


# === Authorization middleware ===

def check_admin_access(token_service: SecureTokenService, token: str) -> bool:
    """Check if a token grants admin access.

    Returns True only if the verified claims contain admin=True.
    """
    try:
        claims = token_service.verify_token(token)
        return claims.get('admin', False) is True
    except (SecurityError, ValueError):
        return False
